'use client'

import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { ReactQueryDevtools } from '@tanstack/react-query-devtools'
import { Toaster } from 'sonner'
import { useState, useEffect } from 'react'
import { useAuthStore } from '@/stores/auth-store'
import { TooltipProvider } from '@/components/ui/tooltip'
import { CrtThemeRoot } from '@/components/theme/crt-theme-root'

/**
 * Service worker registration for web push + offline shell.
 */
function ServiceWorkerRegister() {
  useEffect(() => {
    if (typeof window === 'undefined') return
    if (!('serviceWorker' in navigator)) return
    navigator.serviceWorker.register('/sw.js').catch(() => {
      // Registration failed — push notifications will be unavailable but app still works
    })
  }, [])
  return null
}

/**
 * Auth session checker
 * Validates existing session cookie on mount
 */
function AuthProvider({ children }: { children: React.ReactNode }) {
  const checkSession = useAuthStore((s) => s.checkSession)
  const logout = useAuthStore((s) => s.logout)

  // Check session on mount
  useEffect(() => { checkSession() }, [checkSession])

  // Listen for Supabase auth state changes (token refresh, sign out, etc.)
  useEffect(() => {
    let mounted = true
    let subscription: { unsubscribe: () => void } | null = null

    async function setupAuthListener() {
      try {
        const { createClient } = await import('@/lib/supabase/client')
        if (!mounted) return
        const supabase = createClient()
        const { data } = supabase.auth.onAuthStateChange((event) => {
          if (!mounted) return
          if (event === 'SIGNED_OUT') {
            logout()
          } else if (event === 'TOKEN_REFRESHED') {
            checkSession()
          }
        })
        // Guard against unmount during async gap (React Strict Mode double-effect)
        if (!mounted) {
          data.subscription.unsubscribe()
          return
        }
        subscription = data.subscription
      } catch {
        // Supabase not configured — skip listener
      }
    }

    setupAuthListener()

    return () => {
      mounted = false
      subscription?.unsubscribe()
    }
  }, [checkSession, logout])

  return <>{children}</>
}

/**
 * Root providers wrapper
 * Includes: React Query, Theme, Toaster
 */
export function Providers({ children }: { children: React.ReactNode }) {
  const [queryClient] = useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: {
            // Stale time: 30 seconds (how long data is considered fresh)
            staleTime: 30 * 1000,
            // Cache time: 5 minutes (how long to keep unused data in cache)
            gcTime: 5 * 60 * 1000,
            // Retry failed requests 2 times
            retry: 2,
            // Refetch on window focus (disabled for better UX)
            refetchOnWindowFocus: false,
          },
        },
      })
  )

  return (
    <QueryClientProvider client={queryClient}>
      {/* CRT phosphor-terminal theme. Replaces the old next-themes 13-theme
          provider; theme tokens (--bg/--ph/etc.) resolve from data-* attributes
          CrtThemeRoot sets on <html>, seeded pre-paint by CRT_PREHYDRATION_SCRIPT
          in layout.tsx. Themes are persisted client-side via the crt-settings store. */}
      <CrtThemeRoot />
      <TooltipProvider delayDuration={100}>
        <ServiceWorkerRegister />
        <AuthProvider>{children}</AuthProvider>
      </TooltipProvider>
      <Toaster
        position="top-right"
        closeButton
        duration={5000}
        toastOptions={{
          // CRT-token surface — terminal panel over phosphor border, JetBrains Mono.
          style: {
            background: 'var(--panel)',
            border: '1px solid var(--line)',
            borderRadius: '0',
            color: 'var(--text)',
            fontFamily: 'var(--font-jetbrains), monospace',
          },
        }}
      />
      {process.env.NODE_ENV === 'development' && <ReactQueryDevtools initialIsOpen={false} />}
    </QueryClientProvider>
  )
}

