'use client'

import { useEffect } from 'react'
import { useCrtSettings } from '@/stores/crt-settings-store'

/**
 * Applies CRT settings to the document root as data-* attributes that the
 * globals.css CRT system reads (--bg/--ph/etc. resolve from [data-crt-theme],
 * effects gate on [data-crt]/[data-glow], density on [data-density], public
 * skin on [data-pub-skin]).
 *
 * Setting attributes on <html> (documentElement) keeps the tokens available to
 * portals/modals rendered outside the React tree. The pre-hydration script in
 * layout.tsx sets data-crt-theme before paint to avoid FOUC; this keeps it in
 * sync on change.
 */
export function CrtThemeRoot(): null {
  const { theme, crt, glow, density, pubSkin } = useCrtSettings()

  useEffect(() => {
    const el = document.documentElement
    el.setAttribute('data-crt-theme', theme)
    el.setAttribute('data-crt', crt ? 'on' : 'off')
    el.setAttribute('data-glow', glow ? 'on' : 'off')
    el.setAttribute('data-density', density)
    el.setAttribute('data-pub-skin', pubSkin)
  }, [theme, crt, glow, density, pubSkin])

  return null
}

/**
 * Inline script string for the document <head> — applies the persisted theme
 * before first paint so there's no flash of the default green theme on load.
 * Reads the same localStorage key the Zustand `persist` middleware writes.
 */
export const CRT_PREHYDRATION_SCRIPT = `(function(){try{
var raw=localStorage.getItem('mugenlink-crt-settings');
var s=raw?JSON.parse(raw).state:null;
var el=document.documentElement;
el.setAttribute('data-crt-theme',(s&&s.theme)||'green');
el.setAttribute('data-crt',s&&s.crt===false?'off':'on');
el.setAttribute('data-glow',s&&s.glow===false?'off':'on');
el.setAttribute('data-density',(s&&s.density)||'regular');
el.setAttribute('data-pub-skin',(s&&s.pubSkin)||'terminal');
}catch(e){
document.documentElement.setAttribute('data-crt-theme','green');
}})();`

