import { create } from 'zustand'
import { persist } from 'zustand/middleware'

/**
 * CRT console settings — the v2 design's tweak system, ported to a real store.
 *
 * These map 1:1 to the `data-*` attributes the globals.css CRT system reads on
 * the app root (see ThemeRoot). The prototype's tweaks-panel.jsx is design-time
 * only; in production these surface as user settings (theme/density) + runtime
 * signals (net is driven by connection quality, not a manual toggle in prod).
 */

export type CrtTheme = 'green' | 'ice' | 'amber'
export type Density = 'regular' | 'compact'
export type PubSkin = 'paper' | 'terminal'
export type NetQuality = 'fast' | 'slow' | 'offline'

export const CRT_THEMES: readonly CrtTheme[] = ['green', 'ice', 'amber'] as const

export interface CrtSettingsState {
  theme: CrtTheme
  crt: boolean // scanlines + vignette
  glow: boolean // phosphor glow
  density: Density
  pubSkin: PubSkin
  setTheme: (theme: CrtTheme) => void
  setCrt: (on: boolean) => void
  setGlow: (on: boolean) => void
  setDensity: (density: Density) => void
  setPubSkin: (skin: PubSkin) => void
}

const STORAGE_KEY = 'mugenlink-crt-settings'

export const useCrtSettings = create<CrtSettingsState>()(
  persist(
    (set) => ({
      // Defaults mirror the prototype's TWEAK_DEFAULTS.
      theme: 'green',
      crt: true,
      glow: true,
      density: 'regular',
      pubSkin: 'terminal',
      setTheme: (theme) => set({ theme }),
      setCrt: (crt) => set({ crt }),
      setGlow: (glow) => set({ glow }),
      setDensity: (density) => set({ density }),
      setPubSkin: (pubSkin) => set({ pubSkin }),
    }),
    { name: STORAGE_KEY }
  )
)

