// Console prototype — terminal-style loaders: a "stuck at 90%" ASCII progress
// bar + skeleton shimmer rows. Used on fetch actions (Explorer query, Trace).

function PTermLoad({ label = 'FETCHING', steps, duration = 1600, onDone, width = 30 }) {
  const msgs = steps || ['OPENING SOCKET', 'FETCHING DATA', 'RECONCILING', 'ALMOST THERE…'];
  const [pct, setPct] = React.useState(0);
  React.useEffect(() => {
    let p = 0;
    const id = setInterval(() => {
      // jump to ~90 fast, then crawl — the classic "stuck at 90%"
      if (p < 90) p += Math.random() * 22 + 14;        // ramp: hits ~90 in ~4 ticks (~360ms)
      else p += Math.random() * 0.5 + 0.05;            // crawl: barely moves, sits at 90+
      setPct(Math.min(p, 99.3));
    }, 90);
    const done = setTimeout(() => { clearInterval(id); setPct(100); if (onDone) setTimeout(onDone, 240); }, duration);
    return () => { clearInterval(id); clearTimeout(done); };
  }, []);
  const filled = Math.max(0, Math.min(width, Math.round((pct / 100) * width)));
  const bar = '█'.repeat(filled) + '░'.repeat(width - filled);
  const stuck = pct >= 86 && pct < 100;
  const msg = pct >= 100 ? 'DONE ✓' : stuck ? msgs[msgs.length - 1] : msgs[Math.min(msgs.length - 2, Math.floor((pct / 90) * (msgs.length - 1)))];
  const col = pct >= 100 ? PT.ph : stuck ? PT.amber : PT.ph;
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 11, fontFamily: ptMono }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, fontSize: 10.5, letterSpacing: '.08em' }}>
        <span className="cv-glow" style={{ color: PT.ph, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>❯ {label}</span>
        <span style={{ color: stuck ? PT.amber : PT.mut, whiteSpace: 'nowrap', flexShrink: 0 }}>{msg}{pct < 100 ? <span className="ml-cursor"> ▋</span> : null}</span>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <span className="cv-glow" style={{ fontSize: 12.5, color: col, whiteSpace: 'pre', letterSpacing: 0, overflow: 'hidden' }}>[{bar}]</span>
        <span style={{ fontSize: 12, color: PT.text, minWidth: 42, textAlign: 'right', flexShrink: 0 }}>{Math.floor(pct)}%</span>
      </div>
    </div>
  );
}

function PSkelRows({ rows = 5, cols }) {
  const widths = cols || ['44%', '20%', '16%', '18%'];
  return (
    <div>
      {Array.from({ length: rows }).map((_, r) => (
        <div key={r} style={{ display: 'flex', gap: 14, alignItems: 'center', padding: '8px 14px', borderBottom: '1px solid color-mix(in srgb, var(--line) 45%, transparent)' }}>
          {widths.map((w, c) => (
            <span key={c} className="ml-skel" style={{ height: 9, width: w, display: 'inline-block', flexShrink: 0, opacity: Math.max(0.25, 1 - r * 0.13) }}></span>
          ))}
        </div>
      ))}
    </div>
  );
}

