  const run = () => {
    const parts = val.trim().split(/\s+/);
    const cmd = (parts[0] || '').toLowerCase();
    const arg = parts.slice(1).join(' ');
    if (!cmd) return;
    if (cmd === 'help') {
      setOut(['COMMANDS: ' + P_COMMANDS.map(c => c[1]).join(' / ') + ' — TAB COMPLETES', 'mut']);
    } else if (cmd === 'clear') {
      setOut(null);
