      const a = arg.toUpperCase();
      const tab = P_TABS.find(t => t[0] === a);
      const chain = chains.find(c => c.sym === a);
      if (chain) { actions.gotoChain(chain.sym); setOut([`✓ EXPLORER → ${chain.sym} (${chain.name.toUpperCase()})`, 'ph']); }
      else if (tab) { actions.setTab(a); setOut([`✓ → ${a}`, 'ph']); }
      else setOut([`✗ UNKNOWN TARGET "${a}" — TRY A CHAIN SYM OR TAB NAME`, 'red']);
    } else if (cmd === 'watch') {
