      <span style={{ fontFamily: ptMono, fontSize: 10, color: PT.mut, width: 58, flexShrink: 0 }}>{ts}</span>
      <span className={w.hot ? 'cv-glow' : ''} style={{ fontFamily: ptMono, fontSize: 11, color: w.hot ? PT.amber : PT.ph, flexShrink: 0 }}>{w.hot ? '⚠' : '>>'}</span>
      <span style={{ fontFamily: ptMono, fontSize: 11.5, fontWeight: 700, width: 42, flexShrink: 0, color: PT.text }}>{w.sym}</span>
      <span style={{ fontFamily: ptMono, fontSize: 11.5, color: PT.ph, whiteSpace: 'nowrap' }}>{w.amtStr}</span>
      <span style={{ fontFamily: ptMono, fontSize: 11, color: PT.mut, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
        <span className={actions ? 'ml-invlink' : ''} onClick={actions ? (e => { e.stopPropagation(); actions.investigate(w.from, w.sym); }) : undefined} title={actions ? 'investigate sender' : undefined}>{w.from}</span>
        <span> → </span>
        <span className={actions ? 'ml-invlink' : ''} onClick={actions ? (e => { e.stopPropagation(); actions.investigate(w.to, w.sym); }) : undefined} title={actions ? 'investigate recipient' : undefined}>{w.to}</span>
      </span>
      <span style={{ fontFamily: ptMono, fontSize: 11.5, marginLeft: 'auto', color: PT.amber, flexShrink: 0 }}>{w.usdStr}</span>
    </div>
  );
}

