/* ---------------- EXPLORER ---------------- */
function PExplorer({ chains, selChain, setSelChain, query, setQuery, actions }) {
  const [input, setInput] = React.useState(query || '');
  React.useEffect(() => { setInput(query || ''); }, [query]);
  const [selBlock, setSelBlock] = React.useState(null);
  React.useEffect(() => { setSelBlock(null); }, [query, selChain]);
  const [loading, setLoading] = React.useState(false);
  React.useEffect(() => {
    if (!query) { setLoading(false); return undefined; }
    setLoading(true);
    const id = setTimeout(() => setLoading(false), 1750);
    return () => clearTimeout(id);
  }, [query, selChain]);
  const chain = chains.find(c => c.sym === selChain) || chains[0];
  const qv = (query || '').trim();
  const looksValid = qv.length >= 6 && !/\s/.test(qv);
  const h = query ? pHash(query) : 0;
  const blocks = Array.from({ length: 9 }, (_, i) => ({
    height: chain.height - i,
    txs: 800 + ((chain.height - i) * 37) % 2600,
    size: (0.6 + (((chain.height - i) * 13) % 100) / 80).toFixed(2),
    ago: i === 0 ? 'JUST NOW' : `${i * Math.max(1, Math.round(parseFloat(chain.btLabel)))}${chain.btLabel.includes('s') ? 'S' : 'M'} AGO`,
  }));
  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 8, padding: 8, minHeight: 0 }}>
      {/* Controls */}
      <div style={{ display: 'flex', gap: 8, flexShrink: 0 }}>
        <div style={{ display: 'flex', border: `1px solid ${PT.line}`, background: PT.panel }}>
          {chains.map(c => (
            <span key={c.sym} onClick={() => setSelChain(c.sym)} style={{
              fontFamily: ptMono, fontSize: 10, letterSpacing: '.06em', padding: '8px 10px', cursor: 'pointer',
              color: c.sym === selChain ? PT.bg : PT.mut, background: c.sym === selChain ? PT.ph : 'transparent',
              fontWeight: c.sym === selChain ? 700 : 400, borderRight: '1px solid color-mix(in srgb, var(--line) 55%, transparent)',
            }}>{c.sym}</span>
          ))}
        </div>
        <div style={{ flex: 1, display: 'flex', gap: 0 }}>
          <input
            value={input} onChange={e => setInput(e.target.value)}
            onKeyDown={e => { if (e.key === 'Enter') setQuery(input.trim()); }}
            placeholder={`search ${chain.sym} address / tx / block…`}
            style={{ flex: 1, fontFamily: ptMono, fontSize: 12, background: PT.panel, border: `1px solid ${PT.line}`, borderRight: 'none', color: PT.text, padding: '0 12px', outline: 'none' }}
          ></input>
          <PBtn onClick={() => setQuery(input.trim())} style={{ padding: '0 18px' }}>QUERY ▸</PBtn>
        </div>
      </div>

      <div style={{ flex: 1, display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, minHeight: 0 }}>
        {/* Recent blocks */}
        <PPane title={`RECENT_BLOCKS — ${chain.sym}`} right={`TIP ${pdInt(chain.height)}`}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 90px 80px 110px', padding: '4px 12px 6px', borderBottom: `1px solid ${PT.line}` }}>
            {['HEIGHT', 'TXS', 'MB', 'AGE'].map(x => <span key={x} style={ptH}>{x}</span>)}
          </div>
          <div style={{ flex: 1, overflow: 'auto' }}>
            {blocks.map((b, i) => (
              <div key={b.height} onClick={() => setSelBlock(b)} className={(i === 0 ? 'cv-flash ' : '') + 'cv-row'} style={{ display: 'grid', gridTemplateColumns: '1fr 90px 80px 110px', padding: 'var(--rowpad) 12px', borderBottom: '1px solid color-mix(in srgb, var(--line) 55%, transparent)', cursor: 'pointer' }}>
                <span className={i === 0 ? 'cv-glow' : ''} style={{ fontFamily: ptMono, fontSize: 11.5, color: i === 0 ? PT.ph : PT.text }}>{pdInt(b.height)}</span>
                <span style={{ fontFamily: ptMono, fontSize: 11.5, color: PT.mut }}>{pdInt(b.txs)}</span>
                <span style={{ fontFamily: ptMono, fontSize: 11.5, color: PT.mut }}>{b.size}</span>
                <span style={{ fontFamily: ptMono, fontSize: 10.5, color: PT.mut }}>{b.ago}</span>
              </div>
            ))}
          </div>
        </PPane>

        {/* Query / block result */}
        {selBlock ? (() => {
          const b = selBlock; const bh = pHash('blk' + b.height + chain.sym);
          const pools = ['FOUNDRY USA', 'ANTPOOL', 'F2POOL', 'VIABTC', 'BINANCE POOL', 'MARA POOL', 'SOLO CK'];
          const reward = chain.sym === 'BTC' ? '3.125' : chain.sym === 'BCH' ? '3.125' : chain.sym === 'LTC' ? '6.25' : chain.sym === 'DOGE' ? '10,000' : chain.sym === 'DASH' ? '1.55' : '2.5';
          return (
            <PPane title="BLOCK_RESULT" right={chain.sym} accent={PT.amber}>
              <div style={{ padding: '10px 14px', display: 'grid', gridTemplateColumns: '130px 1fr', rowGap: 8, flexShrink: 0 }}>
                {[
                  ['HEIGHT', pdInt(b.height), PT.ph],
                  ['HASH', '0000' + pHex(bh, 8) + '…' + pHex(bh * 7, 6), PT.text],
                  ['TIMESTAMP', b.ago, PT.text],
                  ['TXNS', pdInt(b.txs), PT.text],
                  ['SIZE', b.size + ' MB', PT.text],
                  ['MINED BY', pools[bh % pools.length], PT.amber],
                  ['BLOCK REWARD', reward + ' ' + chain.sym, PT.text],
                  ['TOTAL FEES', (0.02 + (bh % 80) / 100).toFixed(3) + ' ' + chain.sym, PT.text],
                ].map(([k, v, c]) => (
                  <React.Fragment key={k}>
                    <span style={ptH}>{k}</span>
                    <span className={c === PT.ph ? 'cv-glow' : ''} style={{ fontFamily: ptMono, fontSize: 11.5, color: c, overflow: 'hidden', textOverflow: 'ellipsis' }}>{v}</span>
                  </React.Fragment>
                ))}
              </div>
              <div style={{ padding: '2px 14px 6px', borderBottom: `1px solid ${PT.line}` }}>
                <span style={ptH}>TOP TXNS IN BLOCK</span>
              </div>
              <div style={{ flex: 1, overflow: 'auto', padding: '4px 14px' }}>
                {Array.from({ length: 5 }, (_, i) => {
                  const a = chain.prefix + pHex(bh + i * 13, 4) + '…' + pHex(bh * 5 + i, 4);
                  return (
                    <div key={i} style={{ display: 'flex', gap: 10, padding: '6px 0', borderBottom: '1px solid color-mix(in srgb, var(--line) 55%, transparent)' }}>
                      <span style={{ fontFamily: ptMono, fontSize: 10.5, color: PT.mut, width: 58, flexShrink: 0 }}>{pHex(bh + i, 6)}</span>
                      <span className="ml-invlink" onClick={() => actions.investigate(a, chain.sym)} title="investigate" style={{ fontFamily: ptMono, fontSize: 11, color: PT.text, overflow: 'hidden', textOverflow: 'ellipsis' }}>{a}</span>
                      <span style={{ fontFamily: ptMono, fontSize: 10.5, color: PT.ph, marginLeft: 'auto', whiteSpace: 'nowrap', flexShrink: 0 }}>{pdAmtStr(1 + (bh >> i) % 1400, chain.sym)}</span>
                    </div>
                  );
                })}
              </div>
              <div style={{ display: 'flex', gap: 8, padding: '10px 14px', borderTop: `1px solid ${PT.line}`, flexShrink: 0, alignItems: 'center' }}>
                <PBtn small kind="outline" onClick={() => setSelBlock(null)}>◂ CLOSE</PBtn>
                <span style={ptH}>UTXO + ACCOUNT · {chain.cls}</span>
              </div>
            </PPane>
          );
        })() : query && loading ? (
          <PPane title="ADDRESS_RESULT" right={chain.sym} accent={PT.amber}>
            <div style={{ padding: '20px 16px 14px' }}>
              <PTermLoad label={`RESOLVING ${chain.sym} ADDRESS`} steps={['OPENING SOCKET', `QUERYING ${chain.source || 'INDEX'}`, 'AGGREGATING UTXOS', 'BUILDING 90D FLOW…']} duration={1650}></PTermLoad>
            </div>
            <div style={{ padding: '6px 2px', borderTop: `1px solid ${PT.line}`, marginTop: 6 }}>
              <PSkelRows rows={6} cols={['130px', '40%']}></PSkelRows>
            </div>
          </PPane>
        ) : query && looksValid ? (
          <PPane title="ADDRESS_RESULT" right={chain.sym} accent={PT.amber}>
            <div style={{ padding: '10px 14px', display: 'grid', gridTemplateColumns: '130px 1fr', rowGap: 8, flexShrink: 0 }}>
              {[
                ['ADDR', query, PT.text],
                ['BALANCE', pdAmtStr(10 + h % 14000, chain.sym), PT.ph],
                ['VALUE', pdUsd((10 + h % 14000) * chain.px), PT.amber],
                ['TXS TOTAL', pdInt(12 + h % 8400), PT.text],
                ['FIRST SEEN', `20${17 + h % 8}-${String(1 + h % 12).padStart(2, '0')}-${String(1 + h % 27).padStart(2, '0')}`, PT.text],
                ['LAST ACTIVE', `${1 + h % 22}H AGO`, PT.text],
              ].map(([k, v, c]) => (
                <React.Fragment key={k}>
                  <span style={ptH}>{k}</span>
                  <span className={c === PT.ph ? 'cv-glow' : ''} style={{ fontFamily: ptMono, fontSize: 11.5, color: c, overflow: 'hidden', textOverflow: 'ellipsis' }}>{v}</span>
                </React.Fragment>
              ))}
            </div>
            <div style={{ padding: '2px 14px 6px', borderBottom: `1px solid ${PT.line}` }}>
              <span style={{ fontFamily: ptMono, fontSize: 13, color: PT.ph, opacity: 0.85 }}>{pdBlocksStr(Array.from({ length: 28 }, (_, i) => ((h >> (i % 16)) % 8) / 8))}</span>
              <div style={{ marginTop: 2, marginBottom: 6 }}><span style={ptH}>BALANCE / 90D</span></div>
            </div>
            <div style={{ flex: 1, overflow: 'auto', padding: '4px 14px' }}>
              {Array.from({ length: 5 }, (_, i) => {
                const out = (h >> i) % 2 === 0;
                return (
                  <div key={i} style={{ display: 'flex', gap: 10, padding: '6px 0', borderBottom: '1px solid color-mix(in srgb, var(--line) 55%, transparent)' }}>
                    <span style={{ fontFamily: ptMono, fontSize: 10.5, color: out ? PT.red : PT.ph, width: 32 }}>{out ? 'OUT' : 'IN'}</span>
                    <span style={{ fontFamily: ptMono, fontSize: 11, color: PT.text }}>{pdAmtStr(1 + (h >> (i + 2)) % 900, chain.sym)}</span>
                    <span style={{ fontFamily: ptMono, fontSize: 10.5, color: PT.mut, marginLeft: 'auto' }}>{1 + (h >> i) % 26}H AGO</span>
                  </div>
                );
              })}
            </div>
            <div style={{ display: 'flex', gap: 8, padding: '10px 14px', borderTop: `1px solid ${PT.line}`, flexShrink: 0 }}>
              <PBtn small onClick={() => { const r = actions.addWatch(query); if (r === true) actions.setTab('WATCHLIST'); else actions.openPro('WATCHLIST'); }}>WATCH ▸</PBtn>
              {chain.cls === 'UTXO' ? (
                <PBtn small kind="amber" onClick={() => actions.trace(query, chain.sym)}>TRACE FLOWS ▸</PBtn>
              ) : (
                <span style={{ ...ptH, alignSelf: 'center', padding: '0 4px' }}>TRACING: UTXO CHAINS ONLY</span>
              )}
              <PBtn small kind="outline" onClick={() => setQuery('')}>CLEAR</PBtn>
            </div>
          </PPane>
        ) : query ? (
          <PPane title="NO_MATCH" right={chain.sym} accent={PT.red}>
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 14, padding: 24, textAlign: 'center' }}>
              <span style={{ fontFamily: ptMono, fontSize: 30, color: PT.red, opacity: 0.6 }}>⌀</span>
              <span className="cv-glow" style={{ fontFamily: ptMono, fontSize: 12, letterSpacing: '.1em', color: PT.red }}>NO RESULT</span>
              <span style={{ fontFamily: ptMono, fontSize: 10.5, color: PT.mut, letterSpacing: '.05em', lineHeight: 1.8, maxWidth: 320 }}>
                “{query.length > 28 ? query.slice(0, 28) + '…' : query}” IS NOT A VALID {chain.sym} ADDRESS, TX HASH OR BLOCK HEIGHT. CHECK THE FORMAT AND TRY AGAIN.
              </span>
              <PBtn small kind="outline" onClick={() => setQuery('')}>CLEAR ✕</PBtn>
            </div>
          </PPane>
        ) : (
          <PPane title="QUERY" right="IDLE">
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 12 }}>
              <span style={{ fontFamily: ptMono, fontSize: 24, color: PT.mut, opacity: 0.5 }}>░░▒▒░░</span>
              <span style={{ fontFamily: ptMono, fontSize: 10.5, color: PT.mut, letterSpacing: '.08em', textAlign: 'center', lineHeight: 1.8 }}>
                ENTER AN ADDRESS, TX OR BLOCK.<br></br>RESULTS RENDER HERE.
              </span>
            </div>
          </PPane>
        )}
      </div>
    </div>
  );
}

