/* ---------------- WATCHLIST ---------------- */
function PWatchlist({ watchlist, actions }) {
  const [input, setInput] = React.useState('');
  const [tag, setTag] = React.useState('');
  const [editAddr, setEditAddr] = React.useState(null);
  const [editVal, setEditVal] = React.useState('');
  const commitTag = addr => { actions.setWatchLabel(addr, editVal); setEditAddr(null); };
  const add = () => {
    if (!input.trim()) return;
    const r = actions.addWatch(input.trim(), tag);
    if (r === 'full') actions.openPro('WATCHLIST');
    if (r === true) { setInput(''); setTag(''); }
  };
  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 8, padding: 8, minHeight: 0 }}>
      <PWatchPhase2Banner></PWatchPhase2Banner>
      <div style={{ display: 'flex', gap: 0, flexShrink: 0 }}>
        <input
          value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') add(); }}
          placeholder="paste an address to watch — e.g. bc1q…, addr1q…, ltc1q…"
          style={{ flex: 1, fontFamily: ptMono, fontSize: 12, background: PT.panel, border: `1px solid ${PT.line}`, borderRight: 'none', color: PT.text, padding: '10px 12px', outline: 'none' }}
        ></input>
        <input
          value={tag} onChange={e => setTag(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') add(); }}
          placeholder="tag — e.g. COLD-STORAGE"
          style={{ width: 190, fontFamily: ptMono, fontSize: 11, textTransform: 'uppercase', background: PT.panel, border: `1px solid ${PT.line}`, borderRight: 'none', color: PT.text, padding: '10px 12px', outline: 'none' }}
        ></input>
        <PBtn onClick={add} style={{ padding: '0 20px' }}>WATCH ▸</PBtn>
      </div>
      <PPane title={`WATCHLIST [${watchlist.length}/3] — FREE TIER`} right="[PRO] = 50 ADDRESSES" style={{ flex: 1 }}>
        {watchlist.length === 0 ? (
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 12 }}>
            <span style={{ fontFamily: ptMono, fontSize: 24, color: PT.mut, opacity: 0.5 }}>░░▒▒░░</span>
            <span style={{ fontFamily: ptMono, fontSize: 10.5, color: PT.mut, letterSpacing: '.08em', textAlign: 'center', lineHeight: 1.8 }}>
              NO ADDRESSES WATCHED.<br></br>ADD ONE ABOVE, OR RUN <span style={{ color: PT.ph }}>watch &lt;addr&gt;</span> FROM THE COMMAND BAR.
            </span>
          </div>
        ) : (
          <div style={{ flex: 1, overflow: 'auto' }}>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 130px 70px 110px 150px 90px', padding: '4px 14px 6px', borderBottom: `1px solid ${PT.line}` }}>
              {['ADDRESS', 'TAG', 'CHAIN', 'ACTIVITY', 'TREND / 14D', ''].map((x, i) => <span key={i} style={ptH}>{x}</span>)}
            </div>
            {watchlist.map(w => (
              <div key={w.addr} style={{ display: 'grid', gridTemplateColumns: '1fr 130px 70px 110px 150px 90px', alignItems: 'center', padding: 'var(--rowpad) 14px', borderBottom: '1px solid color-mix(in srgb, var(--line) 55%, transparent)' }}>
                <span className="ml-invlink" onClick={() => actions.investigate(w.addr, w.sym)} title="investigate address" style={{ fontFamily: ptMono, fontSize: 11.5, color: PT.text, overflow: 'hidden', textOverflow: 'ellipsis' }}>{w.addr}</span>
                {editAddr === w.addr ? (
                  <input
                    value={editVal} autoFocus onChange={e => setEditVal(e.target.value)}
                    onKeyDown={e => { if (e.key === 'Enter') commitTag(w.addr); if (e.key === 'Escape') setEditAddr(null); }}
                    onBlur={() => commitTag(w.addr)}
                    style={{ fontFamily: ptMono, fontSize: 10, width: 104, background: 'transparent', border: `1px solid ${PT.line}`, color: PT.text, padding: '2px 6px', outline: 'none', textTransform: 'uppercase' }}
                  ></input>
                ) : w.label ? (
                  <span onClick={() => { setEditAddr(w.addr); setEditVal(w.label); }} title="click to edit tag" style={{ fontFamily: ptMono, fontSize: 9.5, letterSpacing: '.06em', color: PT.ph, border: '1px solid color-mix(in srgb, var(--ph) 35%, transparent)', padding: '2px 7px', cursor: 'pointer', justifySelf: 'start', maxWidth: 112, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{w.label}</span>
                ) : (
                  <span onClick={() => { setEditAddr(w.addr); setEditVal(''); }} style={{ fontFamily: ptMono, fontSize: 9.5, letterSpacing: '.06em', color: PT.mut, cursor: 'pointer' }}>+ TAG</span>
                )}
                <span style={{ fontFamily: ptMono, fontSize: 11, color: PT.mut }}>{w.sym}</span>
                <span style={{ fontFamily: ptMono, fontSize: 11, color: w.txs ? PT.ph : PT.mut }}>{w.txs ? `+${w.txs} TX / 24H` : 'IDLE'}</span>
                <PTrend trend={w.trend} size={11.5} glow={false} color="color-mix(in srgb, var(--ph) 75%, transparent)"></PTrend>
                <span onClick={() => actions.removeWatch(w.addr)} style={{ fontFamily: ptMono, fontSize: 9.5, letterSpacing: '.08em', color: PT.red, cursor: 'pointer', textAlign: 'right' }}>DROP ✕</span>
