            <span style={{ fontFamily: ptMono, fontSize: 10, letterSpacing: '.08em', color: PT.amber }}>3/3 SLOTS USED — FREE TIER LIMIT</span>
            <PBtn kind="amber" small onClick={() => actions.openPro('WATCHLIST')}>RAISE TO 50 [PRO] ▸</PBtn>
          </div>
        ) : null}
      </PPane>
    </div>
  );
}

/* ---------------- ANALYTICS ---------------- */
function PAnalytics({ chains, vol, actions }) {
  const [win, setWin] = React.useState('7D');
  const wins = [['24H', false], ['7D', false], ['30D', true], ['365D', true]];
  const top = chains.slice().sort((a, b) => b.tx24 - a.tx24).slice(0, 6);
  const maxTx = top[0].tx24;
  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 8, padding: 8, minHeight: 0 }}>
      <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexShrink: 0 }}>
        <div style={{ display: 'flex', border: `1px solid ${PT.line}`, background: PT.panel }}>
          {wins.map(([w, pro]) => (
            <span key={w} onClick={() => pro ? actions.openPro('WINDOW') : setWin(w)} style={{
              display: 'flex', alignItems: 'center', gap: 5,
              fontFamily: ptMono, fontSize: 10, letterSpacing: '.06em', padding: '8px 12px', cursor: 'pointer',
              color: w === win ? PT.bg : pro ? PT.mut : PT.text, background: w === win ? PT.ph : 'transparent',
              fontWeight: w === win ? 700 : 400, borderRight: '1px solid color-mix(in srgb, var(--line) 55%, transparent)',
            }}>{w}{pro ? <span style={{ fontSize: 8.5, color: PT.amber }}>[P]</span> : null}</span>
          ))}
        </div>
        <div style={{ display: 'flex', gap: 6, marginLeft: 8 }}>
          <span style={{ fontFamily: ptMono, fontSize: 9.5, letterSpacing: '.08em', color: PT.bg, background: PT.ph, fontWeight: 700, padding: '4px 9px' }}>VELOCITY</span>
          {[['NET_HEALTH', 'HEALTH'], ['COHORTS', 'COHORTS'], ['DATA_FLOW', 'FLOW'], ['NET_GRAPH', 'GRAPH']].map(([s, f]) => (
            <span key={s} onClick={() => actions.openPro(f)} style={{ fontFamily: ptMono, fontSize: 9.5, letterSpacing: '.08em', color: PT.mut, border: `1px solid ${PT.line}`, padding: '4px 9px', cursor: 'pointer' }}>{s} <span style={{ color: PT.amber }}>[P]</span></span>
          ))}
        </div>
        <span style={{ marginLeft: 'auto', ...ptH }}>FREE WINDOW: 7 DAYS</span>
      </div>
      <div style={{ flex: 1, display: 'grid', gridTemplateColumns: '1.4fr 1fr', gap: 8, minHeight: 0 }}>
        <PPane title={`TX_VELOCITY — ${win} — ALL CHAINS`} right="30S RESOLUTION">
          <div style={{ flex: 1, padding: '14px 14px 8px', display: 'flex', flexDirection: 'column', minHeight: 0 }}>
            <div style={{ flex: 1, minHeight: 0, display: 'flex', alignItems: 'stretch' }}>
              <div style={{ flex: 1 }}><PVBars data={vol} height="100%"></PVBars></div>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 8, paddingBottom: 4, flexShrink: 0 }}>
              {(win === '24H' ? ['00:00', '06:00', '12:00', '18:00', 'NOW'] : ['D-7', 'D-5', 'D-3', 'D-1', 'NOW']).map(t => <span key={t} style={ptH}>{t}</span>)}
            </div>
          </div>
        </PPane>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, minHeight: 0 }}>
          <PPane title="SHARE_OF_TXNS — 24H" right="TOP 6" style={{ flex: 1 }}>
            <div style={{ flex: 1, padding: '10px 14px', display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 10, overflow: 'hidden' }}>
              {top.map(c => (
                <div key={c.sym} style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <span style={{ fontFamily: ptMono, fontSize: 10.5, fontWeight: 700, width: 44, color: PT.text }}>{c.sym}</span>
                  <div style={{ flex: 1, height: 10, background: 'rgba(255,255,255,.04)' }}>
                    <div style={{ width: `${Math.round((c.tx24 / maxTx) * 100)}%`, height: '100%', background: PT.ph, opacity: 0.75, boxShadow: 'var(--bar-glow)' }}></div>
                  </div>
                  <span style={{ fontFamily: ptMono, fontSize: 10.5, color: PT.mut, width: 52, textAlign: 'right' }}>{pdK(c.tx24)}</span>
                </div>
              ))}
            </div>
          </PPane>
          <div onClick={() => actions.openPro('WINDOW')} style={{ flexShrink: 0, border: '1px solid color-mix(in srgb, var(--pro) 35%, transparent)', background: 'color-mix(in srgb, var(--pro) 6%, transparent)', padding: '12px 14px', display: 'flex', alignItems: 'center', gap: 12, cursor: 'pointer' }}>
